/**
 * The generated report for the external-corpus run. Every table here is folded
 * from the JSONL rows beside it; nothing is typed in, which is the same rule
 * `bench/deterministic/report.ts` follows and the reason a figure in this
 * project can be checked against the file it came from.
 *
 * The limits are rendered *above* the delivery table rather than under it,
 * because the delivery figure on a backfilled corpus is an upper bound on a
 * process nobody ran and a reader who meets that fact after the number has
 * already read the number.
 */

import { writeFileSync } from 'node:fs';

import type {
  BudgetedLogCoverageRow,
  CorpusIdentity,
  ExternalDeliveryRow,
  ExternalRow,
  RevertBackfillRow,
} from './types.ts';

const pct = (value: number): string => `${(value * 100).toFixed(1)}%`;
const day = (instant: string): string => instant.slice(0, 10);

export const ORACLE_SENTENCE =
  'A backfilled record set is an oracle, not a workflow anyone performed. Every record below was generated by a program from a revert commit, and every one of them is correct by construction because the filter kept only reverts whose change is provably still gone at the pinned SHA. The delivery figures are therefore an **upper bound on a process no user has run**: they say what delivery would look like if a repository\'s revert history had been recorded perfectly and nothing else had been recorded at all.';

export const COVERAGE_SENTENCE =
  '`budgeted_log_coverage` is **not** recall. It is the share of a path\'s commits whose message is wholly inside the 800-token prefix of `git log --format=%B -- P` — the record-free skeleton of the `git-log-path-budgeted` arm. It equals recall only if each commit carries at most one record and records are spread evenly over a path\'s history, which is false in detail everywhere. Read the external figures through the calibration row, never on their own.';

const corpusTable = (identities: readonly CorpusIdentity[]): string[] => [
  '| corpus | licence | pinned SHA | commits | first commit | last commit |',
  '|---|---|---|---:|---|---|',
  ...identities.map(
    (identity) =>
      `| \`${identity.name}\`${identity.calibration ? ' *(calibration)*' : ''} | ` +
      `${identity.licence} | \`${identity.ref.slice(0, 9)}\` | ${identity.commits} | ` +
      `${day(identity.first_commit_at)} | ${day(identity.last_commit_at)} |`,
  ),
];

const coverageTable = (rows: readonly BudgetedLogCoverageRow[]): string[] => [
  '| corpus | paths | commits | coverage @800 | macro | paths at 1.0 | paths at 0 | median commits/path | median tokens/path | p90 tokens/path | full tokens | delivered tokens |',
  '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|',
  ...rows.map(
    (row) =>
      `| \`${row.corpus.name}\` | ${row.evaluation_paths} | ${row.commits_total} | ` +
      `**${pct(row.commit_coverage)}** | ${pct(row.macro_commit_coverage)} | ` +
      `${row.paths_complete} | ${row.paths_zero} | ${row.median_commits_per_path} | ` +
      `${row.median_full_tokens_per_path} | ${row.p90_full_tokens_per_path} | ` +
      `${row.full_tokens} | ${row.budgeted_tokens} |`,
  ),
];

const backfillTable = (rows: readonly RevertBackfillRow[]): string[] => [
  '| corpus | candidates | F1 not one | F2 unresolvable | F3 merge | F4 self-reverted | F5 thin | F6 returned | accepted | at 0.25 | at 0.75 | no reason | truncated | paths |',
  '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|',
  ...rows.map(
    (row) =>
      `| \`${row.corpus.name}\` | ${row.candidates} | ${row.dropped_not_exactly_one} | ` +
      `${row.dropped_unresolvable} | ${row.dropped_merge} | ${row.dropped_self_reverted} | ` +
      `${row.dropped_too_little_content} | ${row.dropped_returned} | **${row.accepted}** | ` +
      `${row.accepted_at_return_threshold_025} | ${row.accepted_at_return_threshold_075} | ` +
      `${row.reason_absent} | ${row.reason_truncated} | ${row.notes_paths_touched} |`,
  ),
];

const deliveryTable = (rows: readonly ExternalDeliveryRow[]): string[] => [
  '| route | budget | path recall | macro | precision | stale delivered | delivered records | delivered tokens | paths at 1.0 | paths at 0 | withheld |',
  '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|',
  ...rows.map(
    (row) =>
      `| ${row.route} | ${row.budget_tokens === null ? '—' : row.budget_tokens} | ` +
      `**${pct(row.path_recall)}** | ${pct(row.macro_path_recall)} | ${pct(row.precision)} | ` +
      `${row.stale_delivered} | ${row.delivered_total} | ${row.delivered_tokens} | ` +
      `${row.paths_complete} | ${row.paths_zero} | ${row.withheld_records} |`,
  ),
];

export const renderExternalReport = (rows: readonly ExternalRow[]): string => {
  const first = rows[0];
  if (first === undefined) throw new Error('no rows to report');
  const coverage = rows.filter(
    (row): row is BudgetedLogCoverageRow => row.metric === 'budgeted_log_coverage',
  );
  const backfill = rows.filter((row): row is RevertBackfillRow => row.metric === 'revert_backfill');
  const delivery = rows.filter(
    (row): row is ExternalDeliveryRow => row.metric === 'decision_delivery',
  );
  const identities = [...new Map(rows.map((row) => [row.corpus.name, row.corpus])).values()];

  const lines: string[] = [
    '# CommitLore on repositories it did not write',
    '',
    `Provenance: harness commit \`${first.harness_commit}\`; harness sha1 \`${first.harness_digest}\`; dist sha256 \`${first.dist_digest}\`.`,
    '',
    `Machine: ${first.machine.cpu}, ${first.machine.logical_cpus} logical CPUs, ${first.machine.platform} ${first.machine.release} (${first.machine.arch}), Node ${first.machine.node}, ${first.machine.git}.`,
    '',
    'The method is registered in `bench/EXTERNAL-CORPUS.md`, written and committed before this harness existed.',
    '',
    '## Corpus',
    '',
    ...corpusTable(identities),
    '',
    'Every figure below is per repository. These results are not poolable: the question is whether a figure measured on one repository describes any other, and an average over five would answer a different question.',
    '',
  ];

  for (const population of ['authored', 'all-tracked'] as const) {
    const scoped = coverage.filter((row) => row.population === population);
    if (scoped.length === 0) continue;
    lines.push(
      population === 'authored'
        ? '## What transfers with no records at all'
        : '### Sensitivity: every tracked path, generated included',
      '',
    );
    if (population === 'authored') lines.push(COVERAGE_SENTENCE, '');
    lines.push(...coverageTable(scoped), '');
  }

  if (backfill.length > 0) {
    lines.push(
      '## Backfill from revert commits',
      '',
      'The funnel of `bench/EXTERNAL-CORPUS.md` §5, in the order the filters run. `at 0.25` and `at 0.75` are how many candidates would have survived the return check at those thresholds instead of the registered 0.5, reported so the threshold is auditable rather than merely declared.',
      '',
      ...backfillTable(backfill),
      '',
    );
  }

  if (delivery.length > 0) {
    lines.push('## Active-record delivery on the backfilled corpus', '', ORACLE_SENTENCE, '');
    lines.push(
      'The two plain Git arms score 0% here by construction: the records are in `refs/notes/commitlore`, which `git log --format=%B` cannot see. `git-log-path-notes-budgeted` is the arm comparable to the 42.0% row — ordinary Git, one command, reading the same records from the same place, cut to the same budget.',
      '',
    );
    for (const identity of identities) {
      for (const population of ['authored', 'all-tracked'] as const) {
        const scoped = delivery.filter(
          (row) => row.corpus.name === identity.name && row.population === population,
        );
        const head = scoped[0];
        if (head === undefined) continue;
        lines.push(
          `### \`${identity.name}\` — ${population === 'authored' ? 'authored paths' : 'every tracked path'}`,
          '',
          `${head.census.records} record(s) over ${head.census.commits_examined} commits — ${head.census.active_records} active, ${head.census.superseded_records} superseded, ${head.census.expired_records} expired at ${head.evaluated_at}. ${head.evaluation_paths} of ${head.candidate_paths} candidate paths carry an active record; the denominator is **${head.path_active_total}** (path, active record) pairs, ${head.rename_only_attachments} of them reachable only through a rename.`,
          '',
          ...deliveryTable(scoped),
          '',
        );
      }
    }
  }

  return `${lines.join('\n')}\n`;
};

export const writeExternalReport = (target: string, rows: readonly ExternalRow[]): void => {
  writeFileSync(target, renderExternalReport(rows));
};
